mapper.select:
	/* file : CodeMapper.xml, id : getCodeMasterList */
	  SELECT A.*
	       , DATE_FORMAT(A.REG_DATE, '%Y-%m-%d') AS REG_DT
	    FROM ST_CODE_MST A
	   WHERE A.DEL_FLAG = 0

	     AND A.GRP_CODE = #{grpCode}

	ORDER BY GRP_CODE
/*||ORDER BY GRP_CODE||*/

/* file : CodeMapper.xml, id : getCodeMaster */
  SELECT A.*
    FROM ST_CODE_MST A
   WHERE A.DEL_FLAG = 0
     AND A.GRP_CODE = #{grpCode}

mapper.insert:
/* file : CodeMapper.xml, id : saveCodeMaster */
INSERT
  INTO ST_CODE_MST (
              GRP_CODE
            , GRP_CODE_NAME
            , REG_USER_SEQ
            , REG_IP)
       VALUES (
              UPPER( #{grpCode} )
            , #{grpCodeName}
            , #{loginUserSeq}
            , #{loginUserIp})
    ON DUPLICATE KEY UPDATE GRP_CODE_NAME = #{grpCodeName}
     , DEL_FLAG                           = 0
     , MOD_USER_SEQ                       = #{loginUserSeq}
     , MOD_DATE                           = CURRENT_TIMESTAMP()
     , MOD_IP                             = #{loginUserIp}

mapper.update:
/* file : CodeMapper.xml, id : deleteCodeMaster */
  UPDATE ST_CODE_MST
     SET DEL_FLAG     = 1
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DATE     = CURRENT_TIMESTAMP()
       , DEL_IP       = #{loginUserIp}
   WHERE GRP_CODE     = #{grpCode}

/* file : CodeMapper.xml, id : deleteCodeMasterDetail */
  UPDATE ST_CODE_DTL
     SET DEL_FLAG     = 1
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DATE     = CURRENT_TIMESTAMP()
       , DEL_IP       = #{loginUserIp}
   WHERE GRP_CODE     = #{grpCode}

mapper.select:
	/* file : CodeMapper.xml, id : getCodeDetailList */
	  SELECT A.*
	       , DATE_FORMAT(A.REG_DATE, '%Y-%m-%d') AS REG_DT
	    FROM ST_CODE_DTL A
	   WHERE A.DEL_FLAG = 0
	     AND A.GRP_CODE = #{grpCode}
	ORDER BY ORDBY
/*||ORDER BY ORDBY||*/

/* file : CodeMapper.xml, id : getCodeDetail */
  SELECT A.*
    FROM ST_CODE_DTL A
   WHERE A.DEL_FLAG = 0
     AND A.GRP_CODE = #{grpCode}
     AND A.CODE     = #{code}

mapper.insert:
/* file : CodeMapper.xml, id : saveCodeDetail */
INSERT
  INTO ST_CODE_DTL (
              GRP_CODE
            , CODE
            , CODE_NAME
            , ORDBY
            , USE_FLAG
            , REG_USER_SEQ
            , REG_IP)
       VALUES (
              UPPER( #{grpCode} )
            , UPPER( #{code} )
            , #{codeName}
            , #{ordby}
            , #{useFlag}
            , #{loginUserSeq}
            , #{loginUserIp})
    ON DUPLICATE KEY UPDATE CODE_NAME = #{codeName}
     , ORDBY                          = #{ordby}
     , USE_FLAG                       = #{useFlag}
     , DEL_FLAG                       = 0
     , MOD_USER_SEQ                   = #{loginUserSeq}
     , MOD_DATE                       = CURRENT_TIMESTAMP()
     , MOD_IP                             = #{loginUserIp}

mapper.update:
/* file : CodeMapper.xml, id : deleteCodeDetail */
  UPDATE ST_CODE_DTL
     SET DEL_FLAG     = 1
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DATE     = CURRENT_TIMESTAMP()
       , DEL_IP       = #{loginUserIp}
   WHERE GRP_CODE     = #{grpCode}
     AND CODE         = #{code}
